<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { communityAssetsApi, type ManagedFile } from '../../infrastructure/communityAssetsApi'
import { t } from '@/shared/i18n'
const items=ref<ManagedFile[]>([]),total=ref(0),bytes=ref(0),page=ref(1),q=ref(''),owner=ref(''),kind=ref(''),attached=ref(''),error=ref(''),loading=ref(false),removing=ref('')
const size=(n:number)=>n<1024?`${n} B`:n<1048576?`${(n/1024).toFixed(1)} KiB`:`${(n/1048576).toFixed(2)} MiB`
async function load(){loading.value=true;error.value='';try{const result=await communityAssetsApi.files({page:page.value,q:q.value,account_id:owner.value,type:kind.value,attached:attached.value});items.value=result.items;total.value=result.total;bytes.value=result.bytes}catch{error.value=t('admin.FilesAdminPage.s30')}finally{loading.value=false}}
function search(){page.value=1;void load()}
async function remove(item:ManagedFile){if(!window.confirm(t('admin.FilesAdminPage.s31', [item.name])))return;removing.value=item.id;error.value='';try{await communityAssetsApi.deleteFile(item.id);await load()}catch{error.value=t('admin.FilesAdminPage.s32')}finally{removing.value=''}}
onMounted(load)
</script>
<template>
 <section class="admin-page">
<header><div><h1>{{ $t('admin.FilesAdminPage.s1') }}</h1><p>{{ $t('admin.FilesAdminPage.s2') }}</p></div></header>
 <form class="admin-toolbar" @submit.prevent="search"><label class="admin-field">{{ $t('admin.FilesAdminPage.s3') }}<input v-model="q" /></label><label class="admin-field">{{ $t('admin.FilesAdminPage.s4') }}<input v-model="owner" inputmode="numeric" /></label><label class="admin-field">{{ $t('admin.FilesAdminPage.s5') }}<select v-model="kind"><option value="">{{ $t('admin.FilesAdminPage.s6') }}</option><option value="image">{{ $t('admin.FilesAdminPage.s7') }}</option><option value="video">{{ $t('admin.FilesAdminPage.s8') }}</option><option value="audio">{{ $t('admin.FilesAdminPage.s9') }}</option><option value="unknown">{{ $t('admin.FilesAdminPage.s10') }}</option></select></label><label class="admin-field">{{ $t('admin.FilesAdminPage.s11') }}<select v-model="attached"><option value="">{{ $t('admin.FilesAdminPage.s6') }}</option><option value="true">{{ $t('admin.FilesAdminPage.s12') }}</option><option value="false">{{ $t('admin.FilesAdminPage.s13') }}</option></select></label><button class="admin-button" :disabled="loading">{{ $t('admin.FilesAdminPage.s14') }}</button></form>
 <p class="admin-description" role="status">{{ $t('admin.FilesAdminPage.s15', [total, size(bytes)]) }}</p><p v-if="error" class="admin-error" role="alert">{{ error }}</p>
 <div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>{{ $t('admin.FilesAdminPage.s16') }}</th><th>{{ $t('admin.FilesAdminPage.s17') }}</th><th>{{ $t('admin.FilesAdminPage.s18') }}</th><th>{{ $t('admin.FilesAdminPage.s19') }}</th><th>{{ $t('admin.FilesAdminPage.s20') }}</th></tr></thead><tbody><tr v-for="item in items" :key="item.id"><td><a :href="item.url" target="_blank" rel="noopener noreferrer">{{ item.name }}</a><small v-if="item.remote">{{ $t('admin.FilesAdminPage.s21') }}</small></td><td>{{ item.account_id }}</td><td>{{ size(item.size) }}<br />{{ item.content_type }}</td><td>{{ item.delete_blocked || $t('admin.FilesAdminPage.s22') }}</td><td><button class="admin-button admin-button--sm admin-button--danger" :disabled="!!item.delete_blocked || !!removing" @click="remove(item)">{{ removing===item.id?$t('admin.FilesAdminPage.s23'):$t('admin.FilesAdminPage.s24') }}</button></td></tr><tr v-if="!loading&&!items.length"><td colspan="5" class="admin-empty">{{ $t('admin.FilesAdminPage.s25') }}</td></tr></tbody></table></div>
 <nav class="admin-pagination" :aria-label="$t('admin.FilesAdminPage.s26')"><button class="admin-button" :disabled="page<=1||loading" @click="page--;load()">{{ $t('admin.FilesAdminPage.s27') }}</button><span>{{ $t('admin.FilesAdminPage.s28', [page]) }}</span><button class="admin-button" :disabled="page*30>=total||loading" @click="page++;load()">{{ $t('admin.FilesAdminPage.s29') }}</button></nav>
</section>
</template>
